# Intermediate unit 69 – American and Australian phrasal verbs. Bám sách: trang 142–143 (đã xem ảnh trang) + đáp án + Mini dictionary. Không chép nguyên văn.
# Tương đương Anh đã có thẻ → chỉ nhắc: mess about/around (u18), freshen up (u32), throw yourself into (u21), lay into (u40), call around (u50).
# Tương đương Anh chưa có thẻ, có định nghĩa ở Mini 69 → thẻ: tell off, suss out, work out (hiểu ra; u42 = tính toán).
# wash up có hai nghĩa (Mỹ / Anh) → hai thẻ; Wait up! (mệnh lệnh) khác wait up (u58 = thức đợi) → thẻ có sense.
theory = (
 P("Most phrasal verbs are shared by all English-speaking countries, but some have regional meanings, and the line between them is blurred: in parts of North America and Australia the British forms are just as common. Films and TV have also carried many US and Australian phrasal verbs to the UK.",
   "Phần lớn phrasal verb dùng chung ở mọi nước nói tiếng Anh, nhưng một số mang nghĩa riêng theo vùng, và ranh giới không rạch ròi: ở nhiều nơi tại Bắc Mỹ và Úc, dạng Anh cũng phổ biến không kém. Phim ảnh, truyền hình cũng đưa nhiều phrasal verb Mỹ, Úc sang Anh.")
 + H("A", "North America", "Bắc Mỹ")
 + T([
   ("bawl sb out (UK: tell off)", "speak angrily to someone", "mắng"),
   ("figure out (UK: work out / suss out)", "find the answer or solution", "nghĩ ra, hiểu ra"),
   ("goof around/off (UK: mess about/around – card in Unit 18)", "act silly or waste time", "đùa nghịch, lười nhác"),
   ("wash up (UK: freshen up – card in Unit 32)", "wash your hands and face; in the UK it means washing the dishes", "rửa mặt mũi tay chân; ở Anh = rửa bát"),
 ])
 + P("Americans sometimes add a particle where British speakers use the verb alone: <b>Wait up!</b> and <b>Listen up!</b> instead of <i>Wait!</i> and <i>Listen!</i> – the <i>up</i> stresses that this is an order. They also <b>visit with</b> friends and <b>meet with</b> colleagues, where a British speaker would just <i>visit</i> or <i>meet</i> them.",
     "Người Mỹ đôi khi thêm tiểu từ khi người Anh chỉ dùng động từ: <b>Wait up!</b> và <b>Listen up!</b> thay cho <i>Wait!</i>, <i>Listen!</i> – <i>up</i> nhấn mạnh đây là mệnh lệnh. Họ cũng <b>visit with</b> bạn bè và <b>meet with</b> đồng nghiệp, trong khi người Anh chỉ nói <i>visit</i> hay <i>meet</i>.")
 + H("B", "Australia", "Úc")
 + T([
   ("barrack for (UK: cheer for)", "support a team or person", "cổ vũ"),
   ("belt into (UK: throw yourself into – card in Unit 21)", "start something fast and with great effort", "lao vào làm"),
   ("get into sb (UK: lay into – card in Unit 40)", "criticise", "chỉ trích"),
   ("shoot through (UK: do a runner)", "leave suddenly and often secretly", "chuồn mất"),
 ])
 + NOTE("<b>Exercise 69.3</b> also uses <i>call around</i> (US for <i>phone around</i> – card in Unit 50).",
        "<b>Bài 69.3</b> còn dùng <i>call around</i> (Mỹ, thay cho <i>phone around</i> – đã có thẻ ở bài 50).")
)
